export const OPA_PUBKEY_ENV = 'ARBITER_OPA_PUBKEY';
export const OPA_SERVICE = 'langguard';
export const OPA_BUNDLE = 'arbiter';
export const OPA_KEY_NAME = 'langguard';
export const OPA_SIGNING_ALGORITHM = 'RS256';
// OPA hides the key from GET /v1/config. A label that names the key is shown there, so a session can tell an OPA that holds an old key from one that holds the current key.
export const OPA_KEY_LABEL = 'arbiter_key';
// The server grants at most 25 s, and a proxy in front of it must allow more.
export const OPA_LONG_POLL_SECONDS = 20;
// OPA turns to these delays when a 200 answer of another type than the long polling type ends its long polling: a server without the wait, or a refused wait.
export const OPA_POLL_MIN_SECONDS = 30;
export const OPA_POLL_MAX_SECONDS = 60;
// A session replaces an OPA that reports another value. Raise it with every change of the arguments that an older OPA must not keep.
export const OPA_LAUNCH_VERSION = 'v2';
export const OPA_LAUNCH_LABEL = 'arbiter_launch';
export const OPA_BUNDLE_PROFILE_HEADER = 'X-Arbiter-Bundle-Profile';
export const OPA_BUNDLE_PROFILE_LOCAL = 'local';

// macOS gives sun_path 104 bytes with the terminating NUL; keep a margin.
export const SOCKET_PATH_LIMIT = 100;

