const rotr = (x: number, n: number): number => (x >>> n) | (x << (32 - n));

export function sha256Hex(text: string): string {
  const bytes = new TextEncoder().encode(text);
  const total = (bytes.length + 9 + 63) & ~63;
  const block = new Uint8Array(total);
  block.set(bytes);
  block[bytes.length] = 0x80;
  const view = new DataView(block.buffer);
  view.setUint32(total - 8, Math.floor((bytes.length * 8) / 0x100000000));
  view.setUint32(total - 4, (bytes.length * 8) >>> 0);
  const h = new Uint32Array([0x6a09e667, 0xbb67ae85, 0x3c6ef372, 0xa54ff53a, 0x510e527f, 0x9b05688c, 0x1f83d9ab, 0x5be0cd19]);
  const w = new Uint32Array(64);
  for (let at = 0; at < total; at += 64) {
    for (let i = 0; i < 16; i++) w[i] = view.getUint32(at + i * 4);
    for (let i = 16; i < 64; i++) {
      const a = w[i - 15] as number;
      const b = w[i - 2] as number;
      w[i] = ((w[i - 16] as number) + (rotr(a, 7) ^ rotr(a, 18) ^ (a >>> 3)) + (w[i - 7] as number) + (rotr(b, 17) ^ rotr(b, 19) ^ (b >>> 10))) >>> 0;
    }
    let [a, b, c, d, e, f, g, hh] = h as unknown as number[] as [number, number, number, number, number, number, number, number];
    for (let i = 0; i < 64; i++) {
      const t1 = (hh + (rotr(e, 6) ^ rotr(e, 11) ^ rotr(e, 25)) + ((e & f) ^ (~e & g)) + (K[i] as number) + (w[i] as number)) >>> 0;
      const t2 = ((rotr(a, 2) ^ rotr(a, 13) ^ rotr(a, 22)) + ((a & b) ^ (a & c) ^ (b & c))) >>> 0;
      hh = g;
      g = f;
      f = e;
      e = (d + t1) >>> 0;
      d = c;
      c = b;
      b = a;
      a = (t1 + t2) >>> 0;
    }
    [a, b, c, d, e, f, g, hh].forEach((v, i) => {
      h[i] = ((h[i] as number) + v) >>> 0;
    });
  }
  return [...h].map((v) => v.toString(16).padStart(8, '0')).join('');
}

const trimmed = (host: string): string => host.trim().replace(/\/+$/, '').toLowerCase();

export const hostHash = (host: string): string => sha256Hex(trimmed(host)).slice(0, 16);

export const opaDir = (home: string): string => `${home.replace(/\/+$/, '')}/.config/arbiter/opa`;

export const opaSocketPath = (home: string, host: string): string => `${opaDir(home)}/${hostHash(host)}.sock`;

export const opaLogPath = (home: string, host: string): string => `${opaDir(home)}/${hostHash(host)}.log`;

export const opaPersistDir = (home: string, host: string): string => `${opaDir(home)}/${hostHash(host)}.bundles`;

export const opaStartLockPath = (home: string, host: string): string => `${opaDir(home)}/${hostHash(host)}.start`;

export const socketPathFits = (path: string): boolean => new TextEncoder().encode(path).length < SOCKET_PATH_LIMIT;

export type OpaSigning = { readonly scope?: string; readonly fingerprint?: string };

// 'fp-' keeps the value a string: OPA reads a --set value of digits only as a number, and a label must be a string.
export const opaKeyFingerprint = (publicKeyPem: string): string => `fp-${sha256Hex(publicKeyPem.trim()).slice(0, 16)}`;

/**
 * The authorization policy of the machine OPA. `path` is the file `mod/opa/system-authz.rego`, loaded from disk and not from the
 * bundle. `digest` is the sha256 of that file and `instance` a random id of this start: both go in as labels, and the policy shows them
 * back at `data.system.authz.attest`, so a later session can find an OPA that an older mod or a person started another way. The facts are labels that the launch set, and a process of the same user can set them too.
 */
export type OpaAuthz = { readonly path: string; readonly digest: string; readonly instance: string };

export const OPA_AUTHZ_INSTANCE_LABEL = 'arbiter_instance';
export const OPA_AUTHZ_DIGEST_LABEL = 'arbiter_authz';

export type OpaLaunchOptions = {
  readonly host: string;
  readonly socketPath: string;
  readonly persistDir: string;
  readonly bearerEnv: string;
  readonly authz: OpaAuthz;
  readonly signing?: OpaSigning & { readonly keyEnv: string };
};

const envRef = (name: string): string => `\${${name}}`;

export function opaLaunchArgs(options: OpaLaunchOptions): string[] {
  const host = options.host.trim().replace(/\/+$/, '');
  const bundle = `bundles.${OPA_BUNDLE}`;
  const service = `services.${OPA_SERVICE}`;
  const sets = [
    `${service}.url=${host}/api/arbiter`,
    `${service}.credentials.bearer.token=${envRef(options.bearerEnv)}`,
    `${service}.headers.${OPA_BUNDLE_PROFILE_HEADER}=${OPA_BUNDLE_PROFILE_LOCAL}`,
    `${bundle}.service=${OPA_SERVICE}`,
    `${bundle}.resource=bundle`,
    `${bundle}.persist=true`,
    `${bundle}.polling.long_polling_timeout_seconds=${OPA_LONG_POLL_SECONDS}`,
    `${bundle}.polling.min_delay_seconds=${OPA_POLL_MIN_SECONDS}`,
    `${bundle}.polling.max_delay_seconds=${OPA_POLL_MAX_SECONDS}`,
    `persistence_directory=${options.persistDir}`,
    `labels.${OPA_AUTHZ_INSTANCE_LABEL}=${options.authz.instance}`,
    `labels.${OPA_AUTHZ_DIGEST_LABEL}=${options.authz.digest}`,
    `labels.${OPA_LAUNCH_LABEL}=${OPA_LAUNCH_VERSION}`,
  ];
  if (options.signing !== undefined) {
    sets.push(
      `keys.${OPA_KEY_NAME}.key=${envRef(options.signing.keyEnv)}`,
      `keys.${OPA_KEY_NAME}.algorithm=${OPA_SIGNING_ALGORITHM}`,
      `${bundle}.signing.keyid=${OPA_KEY_NAME}`,
    );
    if (options.signing.scope !== undefined) sets.push(`${bundle}.signing.scope=${options.signing.scope}`);
    if (options.signing.fingerprint !== undefined) sets.push(`labels.${OPA_KEY_LABEL}=${options.signing.fingerprint}`);
  }
  return [
    'run', '--server', '--addr', `unix://${options.socketPath}`, '--unix-socket-perm', '700', '--authorization=basic', '--log-level', 'error', '--log-format', 'json',
    ...sets.flatMap((set) => ['--set', set]),
    options.authz.path,
  ];
}
